describe('Async Form Submission - Disable Submit Button', () => {
  beforeEach(() => {
    cy.visit('/form');
  });

  it('should disable submit button during successful async form submission', () => {
    // Intercept the form submission API call
    cy.intercept('POST', '/api/submit-form').as('formSubmit');

    // Fill in form fields
    cy.get('[data-testid="name-input"]').type('John Doe');
    cy.get('[data-testid="email-input"]').type('john@example.com');
    cy.get('[data-testid="message-textarea"]').type('This is a test message');

    // Verify submit button is enabled before click
    cy.get('[data-testid="submit-button"]').should('not.be.disabled');
    cy.get('[data-testid="submit-button"]').should('be.visible');

    // Click submit button
    cy.get('[data-testid="submit-button"]').click();

    // Verify submit button is disabled immediately after click
    cy.get('[data-testid="submit-button"]').should('be.disabled');
    cy.get('[data-testid="submit-button"]').should('contain', 'Submitting...');

    // Wait for API response
    cy.wait('@formSubmit').then((interception) => {
      expect(interception.response.statusCode).to.equal(200);
    });

    // Verify success message appears
    cy.get('[data-testid="success-message"]').should('be.visible');
    cy.get('[data-testid="success-message"]').should('contain', 'Form submitted successfully');

    // Verify submit button is re-enabled after success
    cy.get('[data-testid="submit-button"]').should('not.be.disabled');
    cy.get('[data-testid="submit-button"]').should('contain', 'Submit');
  });

  it('should re-enable submit button after failed async form submission', () => {
    // Intercept the form submission API call and mock a failure
    cy.intercept('POST', '/api/submit-form', {
      statusCode: 500,
      body: { error: 'Server error' }
    }).as('formSubmitFailure');

    // Fill in form fields
    cy.get('[data-testid="name-input"]').type('Jane Doe');
    cy.get('[data-testid="email-input"]').type('jane@example.com');
    cy.get('[data-testid="message-textarea"]').type('This form failed');

    // Verify submit button is enabled before click
    cy.get('[data-testid="submit-button"]').should('not.be.disabled');

    // Click submit button
    cy.get('[data-testid="submit-button"]').click();

    // Verify submit button is disabled during submission
    cy.get('[data-testid="submit-button"]').should('be.disabled');
    cy.get('[data-testid="submit-button"]').should('contain', 'Submitting...');

    // Wait for failed API response
    cy.wait('@formSubmitFailure');

    // Verify error message appears
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Server error');

    // Verify submit button is re-enabled after failure
    cy.get('[data-testid="submit-button"]').should('not.be.disabled');
    cy.get('[data-testid="submit-button"]').should('contain', 'Submit');

    // Verify form data is still present
    cy.get('[data-testid="name-input"]').should('have.value', 'Jane Doe');
  });
});
